// Build the email body here rather than in the Gmail node so the escaping
// is explicit — a takeaway is arbitrary text pulled off Hacker News, and it
// is about to be dropped into HTML.
const d = $input.first().json;

const esc = (s) =>
  String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

const rows = d.reports
  .map((r) => {
    const host = (() => {
      try {
        return new URL(r.sourceUrl).hostname.replace(/^www\./, '');
      } catch {
        return 'source';
      }
    })();
    return `
      <tr><td style="padding:14px 0;border-bottom:1px solid #e6e4df;">
        <div style="font:600 15px/1.4 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#15140f;">
          ${esc(r.model)} <span style="font-weight:400;color:#6f6b60;">· ${esc(r.provider)} · ${esc(r.taskCategory)}</span>
        </div>
        <div style="font:400 15px/1.5 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#33312a;margin-top:5px;">
          ${esc(r.takeaway)}
        </div>
        <div style="font:400 12px/1.4 ui-monospace,SFMono-Regular,Menlo,monospace;color:#8a8578;margin-top:6px;">
          <a href="${esc(r.sourceUrl)}" style="color:#8a8578;">${esc(host)} &#8599;</a> · ${esc(r.sourceType)}
        </div>
      </td></tr>`;
  })
  .join('');

const n = d.pendingCount;
const subject = `trackai — ${n} report${n === 1 ? '' : 's'} waiting for review`;

const html = `<!doctype html><html><body style="margin:0;padding:0;background:#faf9f6;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#faf9f6;padding:28px 12px;">
    <tr><td align="center">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:14px;padding:26px;">
        <tr><td>
          <div style="font:800 21px/1.2 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#15140f;">
            ${n} report${n === 1 ? '' : 's'} waiting
          </div>
          <div style="font:400 14px/1.5 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#6f6b60;margin-top:5px;">
            Nothing below is on the site yet. Approve what is worth publishing.
          </div>
        </td></tr>
        <tr><td><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:6px;">${rows}</table></td></tr>
        <tr><td style="padding-top:24px;">
          <a href="${esc(d.reviewUrl)}"
             style="display:inline-block;background:#e8b73a;color:#1a1710;text-decoration:none;font:700 15px/1 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;padding:14px 26px;border-radius:999px;">
            Review &amp; approve
          </a>
          <div style="font:400 12px/1.5 -apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#8a8578;margin-top:14px;">
            No password needed — this link is signed and expires in ${esc(d.linkExpiresInHours)} hours.
            Treat it like a password: anyone with the link can approve or reject these reports.
          </div>
        </td></tr>
      </table>
    </td></tr>
  </table>
</body></html>`;

return [{ json: { subject, html } }];

// Empty queue is the normal case most mornings. Ending quietly beats an
// email that trains you to ignore the ones that matter.
return [];
